using System;
using System.Data;
using System.IO;
namespace Videira {
static class StrategyTests {
 static void Check(bool b,string message){if(!b)throw new Exception(message);}
 public static void Run(){string root=Path.Combine(Environment.CurrentDirectory,"work","Tests20-"+Guid.NewGuid());var s=new Store(root);var company=s.Company;company["Nome fantasia"]="Videira Teste";company["CNPJ"]="00.000.000/0001-00";company["Unidades mês"]=100m;company["Faturamento mês"]=10000m;s.Data.Tables["Plano mensal"].Rows.Add(1,"Gastos fixos","Aluguel",800m);s.Data.Tables["Plano mensal"].Rows.Add(2,"Gastos variáveis","Publicidade mensal",200m);s.Data.Tables["Taxas"].Rows.Find(2)["Percentual"]=3m;
  s.Data.Tables["Produtos"].Rows.Add(1,"VT","Vinho Malbec","Fornecedor interno",50m,80m,10m,"Sim");var p=s.Data.Tables["Produtos"].Rows.Find(1);p["Margem desejada %"]=30m;p["Despesa variável %"]=2m;p["Outros custos unitários"]=2m;p["Precificação automática"]="Sim";p["País"]="Argentina";p["Uva"]="Malbec";p["Safra"]="2022";p["Volume ml"]=750m;var price=s.Price(p,"Crédito à vista");Check(price.Price==96.93m,"Preço divisor com taxa embutida");Check(price.Profit/price.Price>=0.30m,"Meta de margem atingida");var actual=s.CostsAt(p,price.Price);Check(actual.Profit==price.Profit&&actual.Fee==price.Fee,"Custos totais integrados em Produtos e Mercado");Check(s.SellingPrice(p)==price.Price,"Preço único usa taxa de referência");Check(s.Rate("Pix")==0m,"Pix sem desconto de taxa");p["Precificação automática"]="Não";Check(s.SellingPrice(p)==80m,"Preço manual preservado");p["Precificação automática"]="Sim";company["Rateio"]="Por faturamento";Check(s.Price(p,"Crédito à vista").Price==96.37m,"Rateio por faturamento");company["Rateio"]="Por unidade";Check(s.MonthlyPlan*s.SaleAllocationFactor(2m,160m)==20m,"Rateio da venda inclui gastos mensais por todas as unidades");company["Unidades mês"]=0m;bool failed=false;try{s.Price(p,"Pix");}catch{failed=true;}Check(failed,"Meta mensal necessária");company["Unidades mês"]=100m;failed=false;try{s.Calculate(50,1,0,5,95,3);}catch{failed=true;}Check(failed,"Divisor inválido bloqueado");
  var cart=new DataTable();cart.Columns.Add("Produto",typeof(int));cart.Columns.Add("Quantidade",typeof(decimal));cart.Columns.Add("Preço",typeof(decimal));cart.Rows.Add(1,2m,price.Price);int quote=s.Quote(cart,"Cliente Teste","11999999999","Crédito à vista",DateTime.Today.AddDays(7),"Retirada na loja");var q=s.Data.Tables["Orçamentos"].Rows.Find(quote);Check((decimal)p["Estoque"]==10m&&s.Data.Tables["Vendas"].Rows.Count==0,"Orçamento não movimenta estoque");string message=q["Mensagem"].ToString();Check(message.Contains("Argentina")&&message.Contains("Malbec")&&message.Contains("2022")&&message.Contains("750")&&message.Contains("193,86"),"Mensagem com vinho e valores");Check(!message.Contains("Fornecedor interno")&&!message.Contains("Aluguel")&&!message.Contains("margem"),"Dados internos fora da mensagem");s.Save();s=new Store(root);Check(s.Company["Nome fantasia"].ToString()=="Videira Teste"&&s.MonthlyPlan==1000m,"Empresa e planejamento persistidos");Check(s.Data.Tables["Orçamentos"].Rows.Find(quote)["Mensagem"].ToString()==message,"Mensagem histórica preservada");int sale=s.ConvertQuote(quote);Check((decimal)s.Data.Tables["Produtos"].Rows.Find(1)["Estoque"]==8m,"Conversão baixa estoque");Check(s.Data.Tables["Orçamentos"].Rows.Find(quote)["Situação"].ToString()=="Vendido","Situação do orçamento");Check((decimal)s.Data.Tables["Vendas"].Rows.Find(sale)["Taxa R$"]==5.82m,"Taxa sobre preço final");failed=false;try{s.ConvertQuote(quote);}catch{failed=true;}Check(failed&&(decimal)s.Data.Tables["Produtos"].Rows.Find(1)["Estoque"]==8m,"Conversão única");cart.Rows.Clear();cart.Rows.Add(1,9m,price.Price);int unavailable=s.Quote(cart,"Sem estoque","","Pix",DateTime.Today.AddDays(3),"");failed=false;try{s.ConvertQuote(unavailable);}catch{failed=true;}Check(failed&&s.Data.Tables["Vendas"].Rows.Count==1&&s.Data.Tables["Orçamentos"].Rows.Find(unavailable)["Situação"].ToString()=="Aberto","Conversão sem estoque revertida");s=new Store(root);Check(s.Data.Tables["Vendas"].Rows.Count==1,"Reversão persistente");s.Cancel(sale);Check((decimal)s.Finance(DateTime.Today,DateTime.Today).Rows[0][1]==0m,"Financeiro sem orçamento/cancelamento");cart.Rows.Clear();cart.Columns.Add("Preço original",typeof(decimal));cart.Columns.Add("Desconto %",typeof(decimal));cart.Rows.Add(1,2m,72m,80m,10m);int discounted=s.Sell(cart,"Consumidor","Crédito à vista",3m);var dv=s.Data.Tables["Vendas"].Rows.Find(discounted);Check((decimal)dv["Total"]==144m&&(decimal)dv["Taxa R$"]==4.32m&&(decimal)dv["Embalagem"]==2m,"Desconto, taxa e embalagem por unidade");s=new Store(root);var di=s.Data.Tables["Itens"].Select("Venda = "+discounted)[0];Check((decimal)di["Preço original"]==80m&&(decimal)di["Desconto %"]==10m&&(decimal)di["Preço"]==72m,"Histórico de desconto persistido");Directory.Delete(root,true);File.AppendAllText(Path.Combine(Environment.CurrentDirectory,"work","test-result.txt"),"\r\nPASS 2.0: preço com margem e taxa embutida, dois rateios, metas obrigatórias, divisor inválido, empresa, orçamento, mensagem WhatsApp sem custos internos, conversão única e rollback por estoque.");}
}
}

